<?php
namespace App\Http\Controllers;
use App\Models\Partner; use App\Models\Unlock; use App\Models\UnlockParticipation; use App\Services\UnlockStatusService; use App\Services\UnlockParticipationService; use Illuminate\Http\Request; use Illuminate\Support\Str; use Inertia\Inertia;
class PartnerUnlockController extends Controller { private function authorize(Partner $partner,Request $r):void{abort_unless(in_array($r->user()->partners()->whereKey($partner->id)->firstOrFail()->pivot->role,['owner','manager'],true),403);} private function metrics(Unlock $u):array{$counts=$u->participations()->selectRaw("count(*) filter (where status = 'INTERESTED') as interested, count(*) filter (where status in ('COMMITTED','UNLOCKED_PENDING_CONFIRMATION','CONFIRMED','FULFILLED','NO_SHOW')) as committed, count(*) filter (where status = 'CONFIRMED') as confirmed, count(*) filter (where status = 'FULFILLED') as fulfilled, count(*) filter (where status = 'CANCELLED_ON_TIME') as cancelled, count(*) filter (where status = 'EXPIRED') as expired, count(*) filter (where status = 'NO_SHOW') as no_show")->first()->getAttributes();$counts['fulfillment_rate']=$counts['committed']?round($counts['fulfilled']/$counts['committed']*100,1):0;return $counts;} public function index(Request $r,Partner $partner){$this->authorize($partner,$r);$unlocks=Unlock::where('partner_id',$partner->id)->latest()->get();$unlocks->each(fn($u)=>$u->setAttribute('metrics',$this->metrics($u)));return Inertia::render('partner/unlocks/index',['partner'=>$partner->only('name','slug'),'unlocks'=>$unlocks]);} public function form(Request $r,Partner $partner,?Unlock $unlock=null){$this->authorize($partner,$r);if($unlock)abort_unless($unlock->partner_id===$partner->id,404);return Inertia::render('partner/unlocks/form',['partner'=>$partner->only('name','slug'),'unlock'=>$unlock,'locations'=>$partner->locations()->get(['id','name'])]);} public function save(Request $r,Partner $partner,?Unlock $unlock=null){$this->authorize($partner,$r);if($unlock)abort_unless($unlock->partner_id===$partner->id,404);$d=$r->validate(['title'=>'required|string|max:255','short_description'=>'nullable|string','description'=>'nullable|string','terms'=>'nullable|string','type'=>'required|in:BENEFIT,PRICE,EXPERIENCE,SECRET','minimum_commitments'=>'required|integer|min:1','maximum_capacity'=>'nullable|integer|min:1|gte:minimum_commitments','commitment_deadline'=>'nullable|date','free_user_offer'=>'nullable|string','member_offer'=>'nullable|string','location_ids'=>'array','location_ids.*'=>'exists:locations,id']);if($unlock?->participations()->whereIn('status',[UnlockParticipation::COMMITTED,UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION,UnlockParticipation::CONFIRMED,UnlockParticipation::FULFILLED,UnlockParticipation::NO_SHOW])->exists())abort(422,'No puedes modificar condiciones materiales después de compromisos.');$unlock??=new Unlock(['partner_id'=>$partner->id,'origin'=>'PARTNER','created_by_user_id'=>$r->user()->id,'status'=>Unlock::DRAFT]);$unlock->fill($d);$unlock->slug??=Str::slug($d['title']).'-'.Str::lower(Str::random(5));$unlock->save();$unlock->locations()->sync($d['location_ids']??[]);return to_route('partner.unlocks.index',$partner);} public function submit(Request $r,Partner $partner,Unlock $unlock,UnlockStatusService $s){$this->authorize($partner,$r);abort_unless($unlock->partner_id===$partner->id,404);$s->transition($unlock,Unlock::PENDING_REVIEW,$r->user(),null,[Unlock::DRAFT,Unlock::REJECTED]);return back();} public function fulfill(Request $r,Partner $partner,Unlock $unlock,UnlockParticipation $participation,UnlockParticipationService $s){$this->authorize($partner,$r);abort_unless($unlock->partner_id===$partner->id&&$participation->unlock_id===$unlock->id,404);$d=$r->validate(['note'=>'nullable|string|max:2000']);$s->fulfill($participation,$r->user(),'partner_manual',$d['note']??null);return back();}}
